// ── Live risk score from Supabase ─────────────────────────────────────────────
function RiskScoreGauge({ score, label }: { score: number; label: string }) {
  const color = score >= 70 ? "text-destructive" : score >= 40 ? "text-orange-400" : "text-green-400";
  const barColor = score >= 70 ? "bg-destructive" : score >= 40 ? "bg-orange-400" : "bg-green-400";
  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <span>{label}</span>
        <span className={`font-bold tabular-nums ${color}`}>{score}/100</span>
      </div>
      <div className="h-2 rounded-full bg-muted/30 overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-700 ${barColor}`} style={{ width: `${score}%` }} />
      </div>
    </div>
  );
}

